function newBus(){if(!AC)return;if(BUS){const old=BUS;old.gain.setTargetAtTime(0,AC.currentTime,.03);setTimeout(()=>old.disconnect(),400);}BUS=AC.createGain();BUS.connect(MASTER);BUS.connect(VERB);}
function impulse(sec){const r=AC.sampleRate,n=r*sec,b=AC.createBuffer(2,n,r);for(let c=0;c<2;c++){const d=b.getChannelData(c);for(let i=0;i<n;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/n,3);}return b;}
function G(t,a,r,v){const g=AC.createGain();g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(v,t+a);g.gain.exponentialRampToValueAtTime(.0001,t+a+r);g.connect(BUS);return g;}
function O(type,f,t,d){const o=AC.createOscillator();o.type=type;o.frequency.setValueAtTime(f,t);o.start(t);o.stop(t+d+.1);return o;}
function N(t,d){const s=AC.createBufferSource();s.buffer=NB;s.start(t,Math.random()*1.5);s.stop(t+d+.1);return s;}
function Fl(type,f,q=1){const b=AC.createBiquadFilter();b.type=type;b.frequency.value=f;b.Q.value=q;return b;}
const SFX={
  whoosh(t,d=.6,f0=300,f1=3000,v=.45){const n=N(t,d),b=Fl('bandpass',f0,1.4);b.frequency.setValueAtTime(f0,t);b.frequency.exponentialRampToValueAtTime(f1,t+d);n.connect(b).connect(G(t,d*.6,d*.5,v));},
  boom(t,v=.8){const o=O('sine',120,t,1.4);o.frequency.exponentialRampToValueAtTime(36,t+.6);o.connect(G(t,.005,1.3,v));N(t,.3).connect(Fl('lowpass',700)).connect(G(t,.002,.25,v*.5));},
  hit(t,f=160,v=.5){const o=O('sine',f*2,t,.4);o.frequency.exponentialRampToValueAtTime(f,t+.1);o.connect(G(t,.003,.35,v));N(t,.06).connect(Fl('highpass',2500)).connect(G(t,.001,.05,v*.35));},
  tick(t,f=2000,v=.1){O('square',f,t,.05).connect(Fl('bandpass',f,3)).connect(G(t,.001,.035,v));},
  pop(t,f=520,v=.22){const o=O('sine',f*1.8,t,.2);o.frequency.exponentialRampToValueAtTime(f,t+.06);o.connect(G(t,.002,.14,v));},
  chime(t,f=880,v=.2){[[1,1],[2.76,.45],[5.4,.22],[8.93,.1]].forEach(([m,a],k)=>O('sine',f*m,t,3).connect(G(t,.002,2.8/(k+1),v*a)));},
  shimmer(t,d=1.2,v=.07){const sc=[1568,1760,2093,2349,2637,3136,3520,4186];for(let i=0;i<18;i++){const tt=t+Math.random()*d;O('sine',sc[(Math.random()*sc.length)|0],tt,.6).connect(G(tt,.002,.45,v));}},
  riser(t,d=1.4,v=.16){const o=O('sawtooth',110,t,d);o.frequency.exponentialRampToValueAtTime(880,t+d);const b=Fl('lowpass',300,4);b.frequency.setValueAtTime(300,t);b.frequency.exponentialRampToValueAtTime(5000,t+d);const g=AC.createGain();g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(v,t+d*.95);g.gain.linearRampToValueAtTime(.0001,t+d+.04);o.connect(b).connect(g);g.connect(BUS);SFX.whoosh(t,d,400,6000,v*1.4);},
  glitch(t,d=.8,v=.1){for(let i=0;i<16;i++){const tt=t+Math.random()*d,l=.02+Math.random()*.05;O('square',80+Math.random()*1800,tt,l).connect(G(tt,.001,l,v));}N(t,d).connect(Fl('bandpass',1200,.7)).connect(G(t,.01,d,v*.6));},
  sub(t,d=1.5,f=50,v=.45){O('sine',f,t,d).connect(G(t,d*.7,d*.4,v));},
  sonar(t,f=660,v=.16){const o=O('sine',f,t,2);o.frequency.exponentialRampToValueAtTime(f*.97,t+1.8);o.connect(G(t,.005,1.8,v));},
  scratch(t,d=1.5,v=.07){const n=N(t,d),g=AC.createGain();g.gain.setValueAtTime(0,t);for(let x=0;x<d;x+=.05)g.gain.setValueAtTime(v*(.3+Math.random()*.7),t+x);g.gain.setValueAtTime(0,t+d);n.connect(Fl('highpass',2600)).connect(g);g.connect(BUS);},
  pluck(t,f=440,v=.18){const b=Fl('lowpass',4000,1);b.frequency.setValueAtTime(4000,t);b.frequency.exponentialRampToValueAtTime(700,t+.8);b.connect(G(t,.002,1.3,v));O('triangle',f,t,1.5).connect(b);O('sawtooth',f*1.003,t,.4).connect(G(t,.002,.25,v*.22));},
  daf(t,v=.75){const o=O('sine',100,t,.6);o.frequency.exponentialRampToValueAtTime(52,t+.25);o.connect(G(t,.003,.45,v));N(t,.4).connect(Fl('bandpass',3800,.9)).connect(G(t,.002,.3,v*.3));},
  buzz(t,d=1.4,v=.05){const o=O('sawtooth',120,t,d),g=AC.createGain();g.gain.setValueAtTime(0,t);for(let x=0;x<d;x+=.04)g.gain.setValueAtTime(Math.random()<.6?v:0,t+x);g.gain.setValueAtTime(0,t+d);o.connect(Fl('lowpass',1100)).connect(g);g.connect(BUS);},
  swell(t,d=2.5,v=.2){const n=N(t,d),b=Fl('lowpass',300,.7);b.frequency.setValueAtTime(260,t);b.frequency.linearRampToValueAtTime(1500,t+d*.5);b.frequency.linearRampToValueAtTime(280,t+d);const g=AC.createGain();g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(v,t+d*.5);g.gain.linearRampToValueAtTime(.0001,t+d);n.connect(b).connect(g);g.connect(BUS);},
  pad(t,d=3,f=293.66,v=.06){[1,1.5,2,2.52].forEach((m,k)=>[-4,4].forEach(c=>{const o=O('triangle',f*m,t,d);o.detune.value=c;o.connect(Fl('lowpass',1800)).connect(G(t,d*.4,d*.6,v/(k+1)));}));},
  gliss(t,n=9,gap=.07,v=.1,base=293.66){const q=[0,3,6,10,14,17,20,24,27,30,34,38];for(let i=0;i<n;i++)SFX.pluck(t+i*gap,base*Math.pow(2,q[i%q.length]/24),v*(1-i/(n*1.6)));},
  hum(t,d=2,f=147,v=.12){const o=O('sine',f,t,d),l=O('sine',6.5,t,d),lg=AC.createGain();lg.gain.value=f*.03;l.connect(lg).connect(o.frequency);const o2=O('triangle',f*2,t,d);o.connect(G(t,d*.3,d*.7,v));o2.connect(Fl('lowpass',900)).connect(G(t,d*.3,d*.7,v*.4));},
  /* santur arpeggio in Dastgah-e Shur (quarter-tone steps from D) */
  shur(t,gap=.14,v=.17,base=293.66){[0,3,6,10,13,10,6,3,0,-4,0].forEach((q,i)=>SFX.pluck(t+i*gap,base*Math.pow(2,q/24),v));}
};
const PENT=[0,2,4,7,9,12,14,16,19,21,24,26,28,31,33,36,38,40,43];

/* ---------- the motions ---------- */
const D=[];
function def(name,iranUse,bg,build,grp='pick'){D.push({name,iran:!!iranUse,bg,build,grp,tags:[grp,iranUse?'iran':'plain']});}

